// Data first: an array of objects, like rows in a spreadsheet.
const harvests = [
  { farmer: "Amina", crop: "maize", kg: 120 },
  { farmer: "Juma", crop: "beans", kg: 45 },
  { farmer: "Wanjiru", crop: "potatoes", kg: 80 },
];

function makeItem(h) {
  const li = document.createElement("li");
  li.textContent = `${h.farmer}: ${h.kg} kg of ${h.crop}`;  // safe, even if a name holds "<b>"
  if (h.kg >= 100) li.classList.add("big");
  li.dataset.farmer = h.farmer;                              // data-farmer="Amina"
  return li;
}

function buildList(rows) {
  const ul = document.createElement("ul");
  for (const h of rows) ul.appendChild(makeItem(h));
  return ul;
}

// One line puts the finished list on the page.
document.getElementById("report").appendChild(buildList(harvests));

