exercises.solution:
var PATIENTS = [
  { name: "Amina", age: 34, urgent: false },
  { name: "Otieno", age: 71, urgent: true },
  { name: "Chebet", age: 5, urgent: false },
];

function countText(n) {
  return n === 1 ? "1 patient" : `${n} patients`;
}

function showPatients(patients) {
  const list = document.getElementById("patients");
  for (const p of patients) {
    const li = document.createElement("li");
    li.textContent = `${p.name} (age ${p.age})`;
    if (p.urgent) li.classList.add("urgent");
    list.appendChild(li);
  }
  document.getElementById("count").textContent = countText(patients.length);
}

showPatients(PATIENTS);
